import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.CzVS_xMp.js";const h=JSON.parse('{"title":"GPU Systems","description":"","frontmatter":{},"headers":[],"relativePath":"gpu/index.md","filePath":"gpu/index.md","lastUpdated":1788490169000}'),s={name:"gpu/index.md"};function d(n,e,l,i,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="gpu-systems" tabindex="-1">GPU Systems <a class="header-anchor" href="#gpu-systems" aria-label="Permalink to &quot;GPU Systems&quot;">​</a></h1><p>A learning track for GPU architecture and CUDA kernel programming. The goal is to learn how GPUs actually run kernels and why real inference workloads are fast or slow.</p><p>This track is a <strong>hub</strong>: it aggregates a few external courses plus the reference and lab material that supports them. Each folder plays one role — you either <em>learn</em> it (a course), <em>look it up</em> (<code>appendix/</code>), or <em>practice</em> it (<code>labs/</code>).</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Folder</th><th>Role</th><th>Contents</th></tr></thead><tbody><tr><td>[<code>pmpp/</code>](pmpp/</td><td>Course — <strong>primary spine</strong></td><td>Programming Massively Parallel Processors</td></tr><tr><td>[<code>cs149/</code>](cs149/</td><td>Course — systems foundation</td><td>Stanford CS149 Parallel Computing</td></tr><tr><td>[<code>heterogeneous-systems/</code>](heterogeneous-systems/</td><td>Course — complement</td><td>Onur Mutlu parallel-pattern course</td></tr><tr><td>[<code>gpu-mode/</code>](gpu-mode/</td><td>Course — advanced feed</td><td>GPU MODE modern ML kernels</td></tr><tr><td><a href="./articles/"><code>articles/</code></a></td><td>Articles</td><td>Kubernetes GPU sharing and platform notes</td></tr><tr><td><a href="./appendix/"><code>appendix/</code></a></td><td>Reference</td><td>[architecture](appendix/architecture/, [CUDA](appendix/cuda/ docs</td></tr><tr><td><a href="./labs/"><code>labs/</code></a></td><td>Practice</td><td>[profiling](labs/profiling/, [kernels](labs/kernels/</td></tr></tbody></table><p>This split also resolves the CUDA overlap: CUDA-the-course lives in [<code>pmpp/</code>](pmpp/, CUDA-the-reference lives in [<code>appendix/cuda/</code>](appendix/cuda/, and CUDA-the-practice lives in [<code>labs/kernels/</code>](labs/kernels/.</p><h2 id="suggested-path" tabindex="-1">Suggested path <a class="header-anchor" href="#suggested-path" aria-label="Permalink to &quot;Suggested path&quot;">​</a></h2><ol><li><strong>Spine:</strong> work through [PMPP](pmpp/ as the primary course.</li><li><strong>Systems foundation:</strong> use [Stanford CS149](cs149/ to connect CUDA kernels with CPU parallelism, scheduling, locality, synchronization, memory models, and DNN execution.</li><li><strong>Complement:</strong> use [Heterogeneous Systems (Onur Mutlu)](heterogeneous-systems/ in parallel for a second pass over the classic parallel patterns.</li><li><strong>Practice as you go:</strong> for each concept, implement and profile a real kernel in <a href="./labs/"><code>labs/</code></a> and confirm the behavior with [Nsight Compute](labs/profiling/.</li><li><strong>Reference on demand:</strong> consult <a href="./appendix/"><code>appendix/</code></a> for the exact NVIDIA architecture and CUDA API details.</li><li><strong>Later / advanced:</strong> track [GPU MODE](gpu-mode/ as an ongoing feed for modern ML kernels.</li></ol>',8)])])}const m=t(s,[["render",d]]);export{h as __pageData,m as default};
